// VCS coverage exclude_file
module Gaux_ram_4x173(
  input  [1:0]   R0_addr,
  input          R0_en,
                 R0_clk,
  output [172:0] R0_data,
  input  [1:0]   W0_addr,
  input          W0_en,
                 W0_clk,
  input  [172:0] W0_data
);

  reg [172:0] Memory[0:3];
  always @(posedge W0_clk) begin
    if (W0_en)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 173'bx;
endmodule

module Gaux_Queue4_InTileQueueTask(
  input         clock,
                reset,
  output        io_enq_ready,
  input         io_enq_valid,
  input  [15:0] io_enq_bits_mean2d_mean2dX,
                io_enq_bits_mean2d_mean2dY,
                io_enq_bits_invCov2d_covX,
                io_enq_bits_invCov2d_covY,
                io_enq_bits_invCov2d_covZ,
                io_enq_bits_radii,
                io_enq_bits_gaussRenParams_color_R,
                io_enq_bits_gaussRenParams_color_G,
                io_enq_bits_gaussRenParams_color_B,
                io_enq_bits_gaussRenParams_opacity,
  input  [12:0] io_enq_bits_gid,
  input         io_deq_ready,
  output        io_deq_valid,
  output [15:0] io_deq_bits_mean2d_mean2dX,
                io_deq_bits_mean2d_mean2dY,
                io_deq_bits_invCov2d_covX,
                io_deq_bits_invCov2d_covY,
                io_deq_bits_invCov2d_covZ,
                io_deq_bits_radii,
                io_deq_bits_gaussRenParams_color_R,
                io_deq_bits_gaussRenParams_color_G,
                io_deq_bits_gaussRenParams_color_B,
                io_deq_bits_gaussRenParams_opacity,
  output [12:0] io_deq_bits_gid,
  output [2:0]  io_count
);

  wire [172:0] _ram_ext_R0_data;
  reg  [1:0]   enq_ptr_value;
  reg  [1:0]   deq_ptr_value;
  reg          maybe_full;
  wire         ptr_match = enq_ptr_value == deq_ptr_value;
  wire         empty = ptr_match & ~maybe_full;
  wire         full = ptr_match & maybe_full;
  wire         do_enq = ~full & io_enq_valid;
  always @(posedge clock) begin
    if (reset) begin
      enq_ptr_value <= 2'h0;
      deq_ptr_value <= 2'h0;
      maybe_full <= 1'h0;
    end
    else begin
      automatic logic do_deq = io_deq_ready & ~empty;
      if (do_enq)
        enq_ptr_value <= enq_ptr_value + 2'h1;
      if (do_deq)
        deq_ptr_value <= deq_ptr_value + 2'h1;
      if (do_enq != do_deq)
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  Gaux_ram_4x173 ram_ext (
    .R0_addr (deq_ptr_value),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (_ram_ext_R0_data),
    .W0_addr (enq_ptr_value),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data
      ({io_enq_bits_mean2d_mean2dX,
        io_enq_bits_mean2d_mean2dY,
        io_enq_bits_invCov2d_covX,
        io_enq_bits_invCov2d_covY,
        io_enq_bits_invCov2d_covZ,
        io_enq_bits_radii,
        io_enq_bits_gaussRenParams_color_R,
        io_enq_bits_gaussRenParams_color_G,
        io_enq_bits_gaussRenParams_color_B,
        io_enq_bits_gaussRenParams_opacity,
        io_enq_bits_gid})
  );
  assign io_enq_ready = ~full;
  assign io_deq_valid = ~empty;
  assign io_deq_bits_mean2d_mean2dX = _ram_ext_R0_data[172:157];
  assign io_deq_bits_mean2d_mean2dY = _ram_ext_R0_data[156:141];
  assign io_deq_bits_invCov2d_covX = _ram_ext_R0_data[140:125];
  assign io_deq_bits_invCov2d_covY = _ram_ext_R0_data[124:109];
  assign io_deq_bits_invCov2d_covZ = _ram_ext_R0_data[108:93];
  assign io_deq_bits_radii = _ram_ext_R0_data[92:77];
  assign io_deq_bits_gaussRenParams_color_R = _ram_ext_R0_data[76:61];
  assign io_deq_bits_gaussRenParams_color_G = _ram_ext_R0_data[60:45];
  assign io_deq_bits_gaussRenParams_color_B = _ram_ext_R0_data[44:29];
  assign io_deq_bits_gaussRenParams_opacity = _ram_ext_R0_data[28:13];
  assign io_deq_bits_gid = _ram_ext_R0_data[12:0];
  assign io_count = {full, enq_ptr_value - deq_ptr_value};
endmodule

