module Gaux_Switch(
  input         io_in_0_valid,
  input  [35:0] io_in_0_bits,
  input         io_in_1_valid,
  input  [35:0] io_in_1_bits,
  output        io_out_0_valid,
  output [35:0] io_out_0_bits,
  output        io_out_1_valid,
  output [35:0] io_out_1_bits,
  input         io_cfg
);

  assign io_out_0_valid = io_cfg ? io_in_0_valid : io_in_1_valid;
  assign io_out_0_bits = io_cfg ? io_in_0_bits : io_in_1_bits;
  assign io_out_1_valid = io_cfg ? io_in_1_valid : io_in_0_valid;
  assign io_out_1_bits = io_cfg ? io_in_1_bits : io_in_0_bits;
endmodule

module Gaux_MuxTree(
