);

  assign io_out_valid = io_cfg ? io_in_0_valid : io_in_1_valid;
  assign io_out_bits = io_cfg ? io_in_0_bits : io_in_1_bits;
endmodule

module Gaux_LROTC(
  input  io_prefixSum,
  output io_configBit_0
);

  assign io_configBit_0 = io_prefixSum;
endmodule

module Gaux_LROTC_8(
  input  [1:0] io_prefixSum,
  output       io_configBit_0,
               io_configBit_1
);

  assign io_configBit_0 =
    io_prefixSum[0] ? ~(io_prefixSum[1]) : ~(io_prefixSum[0]) & io_prefixSum[1];
  assign io_configBit_1 = io_prefixSum[1];
endmodule

module Gaux_LROTC_12(
  input  [2:0] io_prefixSum,
  output       io_configBit_0,
               io_configBit_1,
               io_configBit_2,
               io_configBit_3
);

  wire       _GEN = io_prefixSum[1:0] == 2'h0;
  wire       _GEN_0 = io_prefixSum[1:0] == 2'h2;
  wire       _GEN_1 = io_prefixSum[1:0] == 2'h1;
  wire [3:0] _GEN_2 =
    {{~(io_prefixSum[2])},
     {~(io_prefixSum[2])},
     {~(io_prefixSum[2])},
     {_GEN & io_prefixSum[2]}};
  assign io_configBit_0 = _GEN_2[io_prefixSum[1:0]];
  assign io_configBit_1 =
    _GEN_0
      ? ~(io_prefixSum[2])
      : (&(io_prefixSum[1:0])) ? ~(io_prefixSum[2]) : (_GEN | _GEN_1) & io_prefixSum[2];
  assign io_configBit_2 =
    (&(io_prefixSum[1:0]))
      ? ~(io_prefixSum[2])
      : (_GEN | _GEN_1 | _GEN_0) & io_prefixSum[2];
  assign io_configBit_3 =
    (_GEN | _GEN_1 | _GEN_0 | (&(io_prefixSum[1:0]))) & io_prefixSum[2];
endmodule

module Gaux_LROTC_14(
  input  [3:0] io_prefixSum,
  output       io_configBit_0,
               io_configBit_1,
               io_configBit_2,
               io_configBit_3
);

  wire       _GEN = io_prefixSum[2:0] == 3'h0;
  wire       _GEN_0 = io_prefixSum[2:0] == 3'h2;
  wire       _GEN_1 = io_prefixSum[2:0] == 3'h1;
  wire [7:0] _GEN_2 =
    {{~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {_GEN & io_prefixSum[3]}};
  wire       _GEN_3 = (_GEN | _GEN_1) & io_prefixSum[3];
  wire [7:0] _GEN_4 =
    {{~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {_GEN_3},
     {_GEN_3}};
  wire       _GEN_5 = (_GEN | _GEN_1 | _GEN_0) & io_prefixSum[3];
  wire [7:0] _GEN_6 =
    {{~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {~(io_prefixSum[3])},
     {_GEN_5},
     {_GEN_5},
     {_GEN_5}};
  assign io_configBit_0 = _GEN_2[io_prefixSum[2:0]];
  assign io_configBit_1 = _GEN_4[io_prefixSum[2:0]];
  assign io_configBit_2 = _GEN_6[io_prefixSum[2:0]];
  assign io_configBit_3 =
    io_prefixSum[2:0] == 3'h4
      ? ~(io_prefixSum[3])
      : io_prefixSum[2:0] == 3'h5
          ? ~(io_prefixSum[3])
          : io_prefixSum[2:0] == 3'h6
              ? ~(io_prefixSum[3])
              : (&(io_prefixSum[2:0]))
                  ? ~(io_prefixSum[3])
                  : (_GEN | _GEN_1 | _GEN_0 | io_prefixSum[2:0] == 3'h3)
                    & io_prefixSum[3];
endmodule

