          ? 3'h1
          : io_fixedX[3] ? 3'h2 : io_fixedX[2] ? 3'h3 : {2'h2, ~(io_fixedX[1])};
  wire [12:0] _rawMant_T = {7'h0, io_fixedX} << lzCount;
  assign io_floatY =
    {1'h0,
     (|(_rawMant_T[5:0])) ? 5'h14 - {2'h0, lzCount} : 5'h0,
     (|(_rawMant_T[5:0])) ? {_rawMant_T[4:0], 5'h0} : 10'h0};
