// VCS coverage exclude_file
module Gaux_ram_2x376(
  input          R0_addr,
                 R0_en,
                 R0_clk,
  output [375:0] R0_data,
  input          W0_addr,
                 W0_en,
                 W0_clk,
  input  [375:0] W0_data
);

  reg [375:0] Memory[0:1];
  always @(posedge W0_clk) begin
    if (W0_en)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 376'bx;
endmodule

