module Gaux_Fix2Float_1(
  input  [11:0] io_fixedX,
  output [15:0] io_floatY
);

  wire [3:0]  lzCount =
    io_fixedX[11]
      ? 4'h0
      : io_fixedX[10]
          ? 4'h1
          : io_fixedX[9]
              ? 4'h2
              : io_fixedX[8]
                  ? 4'h3
                  : io_fixedX[7]
                      ? 4'h4
                      : io_fixedX[6]
                          ? 4'h5
                          : io_fixedX[5]
                              ? 4'h6
                              : io_fixedX[4]
                                  ? 4'h7
                                  : io_fixedX[3]
                                      ? 4'h8
                                      : io_fixedX[2] ? 4'h9 : {3'h5, ~(io_fixedX[1])};
  wire [26:0] _rawMant_T = {15'h0, io_fixedX} << lzCount;
  assign io_floatY =
    {1'h0,
     (|(_rawMant_T[11:0])) ? 5'h1A - {1'h0, lzCount} : 5'h0,
     (|(_rawMant_T[11:0])) ? _rawMant_T[10:1] : 10'h0};
endmodule

