    io_ext_readData_REG <=
      {_mem_1_rw_dataOut_a,
       _mem_2_rw_dataOut_a[15:8],
       _mem_rw_dataOut_a,
       _mem_2_rw_dataOut_a[7:0]};
    io_int_vr_readData_REG <= ~(io_int_vr_address[11]);
  end // always @(posedge)
  Gaux_SramWrapperDp #(
    .ADDR_WIDTH(11),
    .DATA_WIDTH(72),
    .DEPTH(2048)
  ) mem (
    .clock        (clock),
