    .rw_enable_b  (_GEN_1 ? intSramPorts_vr_0_enable : io_int_pp_1_enable),
    .rw_addr_b    (_GEN_1 ? io_int_vr_address[10:0] : io_int_pp_1_address),
    .rw_write_b   (1'h0),
    .rw_dataIn_b  (72'h0),
    .rw_dataOut_b (_mem_rw_dataOut_b),
    .rw_bweb_b    (72'h0)
  );
  Gaux_SramWrapperDp #(
    .ADDR_WIDTH(11),
    .DATA_WIDTH(72),
    .DEPTH(2048)
  ) mem_1 (
    .clock        (clock),
    .rw_enable_a  (io_int_pp_0_enable | io_ext_enable),
    .rw_addr_a    (io_int_pp_0_enable ? io_int_pp_0_address : io_ext_address),
    .rw_write_a   (io_int_pp_0_enable | io_ext_isWrite),
    .rw_dataIn_a
      (io_int_pp_0_enable ? io_int_pp_0_writeData[159:88] : io_ext_writeData[159:88]),
    .rw_dataOut_a (_mem_1_rw_dataOut_a),
