    .rw_dataIn_a
      (io_int_pp_0_enable
         ? {io_int_pp_0_writeData[87:80], io_int_pp_0_writeData[7:0]}
         : {io_ext_writeData[87:80], io_ext_writeData[7:0]}),
    .rw_dataOut_a (_mem_2_rw_dataOut_a),
    .rw_bweb_a    (io_int_pp_0_enable ? 16'h0 : {io_ext_bweb[87:80], io_ext_bweb[7:0]}),
    .rw_enable_b  (_GEN_3 ? io_int_vr_enable : io_int_pp_1_enable),
