    .rw_dataOut_b (_mem_2_rw_dataOut_b),
    .rw_bweb_b    (_GEN_3 ? (io_int_vr_address[11] ? 16'hFF : 16'hFF00) : 16'h0)
  );
  assign io_ext_readData = io_ext_readData_REG;
  assign io_int_pp_1_readData =
    {_mem_1_rw_dataOut_b,
     _mem_2_rw_dataOut_b[15:8],
     _mem_rw_dataOut_b,
     _mem_2_rw_dataOut_b[7:0]};
  assign io_int_vr_readData =
    io_int_vr_readData_REG
