      ? io_int_sort_enable & ~(io_int_sort_address[11])
      : io_int_vr_enable & ~(io_int_vr_address[11]);
  wire        intSramPorts_1_enable =
    _GEN
      ? io_int_sort_enable & io_int_sort_address[11]
      : io_int_vr_enable & io_int_vr_address[11];
  always @(posedge clock) begin
    io_ext_readData_REG <= ~(io_ext_address[11]);
    io_ext_readData_REG_1 <= io_ext_readData_REG ? _mem_rw_dataOut : _mem_1_rw_dataOut;
    io_int_vr_readData_REG <= ~(io_int_vr_address[11]);
