         ? (_GEN ? io_int_sort_address[10:0] : io_int_vr_address[10:0])
         : io_ext_address[10:0]),
    .rw_write
      (intSramPorts_0_enable
         ? _GEN & ~(io_int_sort_address[11])
         : io_ext_isWrite & ~(io_ext_address[11])),
    .rw_dataIn
