  Gaux_SramWrapperSp #(
    .ADDR_WIDTH(11),
    .DATA_WIDTH(64),
    .DEPTH(2048)
  ) mem_1 (
    .clock      (clock),
    .rw_enable  (intSramPorts_1_enable | io_ext_enable & io_ext_address[11]),
    .rw_addr
      (intSramPorts_1_enable
         ? (_GEN ? io_int_sort_address[10:0] : io_int_vr_address[10:0])
         : io_ext_address[10:0]),
    .rw_write
      (intSramPorts_1_enable
         ? _GEN & io_int_sort_address[11]
         : io_ext_isWrite & io_ext_address[11]),
    .rw_dataIn
