    .rw_dataOut (_mem_1_rw_dataOut),
    .rw_bweb
      (intSramPorts_1_enable ? (_GEN ? 64'hFFFFFFFF00000000 : 64'h0) : io_ext_bweb)
  );
  assign io_ext_readData = io_ext_readData_REG_1;
